file_system_access_token = login_result["access_token"]
files = apis.file_system.show_directory(
    access_token=file_system_access_token,
    directory_path='~/photographs/vacations/'
)
file_details = []
for file in files:
    file_info = apis.file_system.show_file(
        access_token=file_system_access_token,
        file_path=file
    )
    file_details.append({
        "file_path": file,
        "creation_date": file_info["creation_date"]
    })
print(file_details)

