 "method": "GET",
 "description": "Get detailed information about a specific playlist. You can view your own playlists or others' playlists if they are public.",
 "parameters": [
  {
   "name": "playlist_id",
   "type": "integer",
   "required": true,
   "description": "The playlist id to retrieve.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": false,
   "description": "Access token obtained from spotify app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "playlist_id": 1,
   "title": "string",
   "is_public": true,
   "rating": 0.0,
   "like_count": 1,
   "review_count": 1,
   "owner": {
    "name": "string",
    "email": "user@example.com"
   },
   "created_at": "2019-01-01T00:00:00",
   "shareable_link": "string",
   "songs": [
    {
     "id": 1,
     "title": "string",
     "album_id": 1,
     "album_title": "string",
     "duration": 1,
     "artists": [
      {
       "id": 1,
       "name": "string"
      }
     ]
    }
   ]
  },
  "failure": {
   "message": "string"
  }
 }
}

