# Get the details of the Velvet Underground album
velvet_underground_album = None
for album in album_search_result:
    if album["title"] == "Velvet Underground":
        velvet_underground_album = album
        break

# Use the show_album API to get the details of the Velvet Underground album
if velvet_underground_album:
    album_id = velvet_underground_album["album_id"]
    album_details = apis.spotify.show_album(album_id=album_id)
    print(album_details)
else:
    print("Velvet Underground album not found.")

